mapper.sql:
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.DEL_YN = 'N'
  /* 스코프 필터: master/safe(companyWide=true)는 회사 전체, 그 외는 자기 사업장만 */

    AND A.SITE_CD = #{scopeSiteCd}



      AND A.STATUS_CD = #{statusCd}


      AND A.STATUS_CD IN ('COMPLETED', 'CANCELLED')



    AND A.SITE_CD = #{siteCd}


    AND A.MANAGER_USER_CD = #{managerUserCd}


    AND A.TITLE LIKE CONCAT('%', #{searchKeyword}, '%')

  /* 기간 필터: 종료일(ENDED_AT) 기준, 미종료(CANCELLED 등)는 등록일 보완 */

    AND DATE(IFNULL(A.ENDED_AT, A.INSERT_DATE)) >= #{startDate}


    AND DATE(IFNULL(A.ENDED_AT, A.INSERT_DATE)) <= #{endDate}

mapper.select:
/* Tbm04Mapper.selectHistorySessionListCount */
SELECT COUNT(1)
FROM TB_TBM_SESSION A

/* Tbm04Mapper.selectSessionAttendances */ SELECT AT.ATTENDANCE_CD AS attendanceCd , AT.USER_TYPE_CD AS userTypeCd , TP.SYST_VAL_D_NM AS userTypeNm , AT.USER_CD AS userCd , CASE WHEN AT.USER_TYPE_CD = 'REGULAR' THEN RU.USER_NM ELSE DU.USER_NM END AS userNm , ND.NODE_NM AS deptNm , DU.MBL_NO_LAST4 AS mblNoLast4 , AT.ENTRY_TYPE_CD AS entryTypeCd , DATE_FORMAT(AT.ENTRY_AT, '%Y-%m-%d %H:%i') AS entryAt , AT.EXIT_TYPE_CD AS exitTypeCd , DATE_FORMAT(AT.EXIT_AT, '%Y-%m-%d %H:%i') AS exitAt , AT.EXIT_FORCED_REASON AS exitForcedReason , AT.ENTRY_SIGN_FILE_MGMT_CD AS entrySignFileMgmtCd , AT.EXIT_SIGN_FILE_MGMT_CD AS exitSignFileMgmtCd , AT.COMPLETION_STATUS_CD AS completionStatusCd , CS.SYST_VAL_D_NM AS completionStatusNm , AT.NOT_COMPLETED_REASON AS notCompletedReason , AT.STATUS_UPDATED_BY AS statusUpdatedBy , FNC_CMM_INFO_SRCH(AT.CMPNY_CD, 'USER_NM', AT.STATUS_UPDATED_BY, NULL) AS statusUpdatedByNm , DATE_FORMAT(AT.STATUS_UPDATED_AT, '%Y-%m-%d %H:%i') AS statusUpdatedAt /* prafta-051-08: 앱 포그라운드 누적초(051-16 표시용, NULL=미수신/대리입실) */ , AT.APP_FOREGROUND_SEC AS appForegroundSec /* prafta-051-16: 입실 GPS 거리(m). 대리/검색입실은 NULL */ , AT.ENTRY_DISTANCE_M AS entryDistanceM /* 이상신호 요약(백엔드 집계) */ , ( SELECT COUNT(1) FROM TB_TBM_ATTENDANCE_EVENT EV WHERE EV.CMPNY_CD = AT.CMPNY_CD AND EV.ATTENDANCE_CD = AT.ATTENDANCE_CD AND EV.EVENT_TYPE_CD = 'BACKGROUND_OUT' ) AS backgroundCount , ( SELECT COUNT(1) FROM TB_TBM_ATTENDANCE_EVENT EV WHERE EV.CMPNY_CD = AT.CMPNY_CD AND EV.ATTENDANCE_CD = AT.ATTENDANCE_CD AND EV.EVENT_TYPE_CD = 'GPS_UPDATED' AND JSON_EXTRACT(EV.EVENT_DATA, '$.outOfRange') = TRUE ) AS gpsOutOfRangeCount , ( SELECT COUNT(1) FROM TB_TBM_ATTENDANCE_EVENT EV WHERE EV.CMPNY_CD = AT.CMPNY_CD AND EV.ATTENDANCE_CD = AT.ATTENDANCE_CD AND EV.EVENT_TYPE_CD = 'NETWORK_LOST' ) AS networkLostCount , ( SELECT COUNT(1) FROM TB_TBM_ATTENDANCE_EVENT EV WHERE EV.CMPNY_CD = AT.CMPNY_CD AND EV.ATTENDANCE_CD = AT.ATTENDANCE_CD ) AS eventCount FROM TB_TBM_ATTENDANCE AT LEFT OUTER JOIN TB_USER RU ON ( AT.USER_TYPE_CD = 'REGULAR' AND AT.CMPNY_CD = RU.CMPNY_CD AND AT.USER_CD = RU.USER_CD ) LEFT OUTER JOIN TB_DAILY_USER DU ON ( AT.USER_TYPE_CD = 'DAILY' AND AT.CMPNY_CD = DU.CMPNY_CD AND AT.USER_CD = DU.USER_CD ) LEFT OUTER JOIN TB_SITE_NODE ND ON ( AT.USER_TYPE_CD = 'REGULAR' AND RU.CMPNY_CD = ND.CMPNY_CD AND RU.SITE_CD = ND.SITE_CD AND RU.NODE_CD = ND.NODE_CD ) LEFT OUTER JOIN ( SELECT D.SYST_VAL_D_CD, D.SYST_VAL_D_NM FROM TB_SYST_VAL_D D WHERE D.SYST_VAL_CD = 'SYS050' AND D.USE_YN = 'Y' ) TP ON ( AT.USER_TYPE_CD = TP.SYST_VAL_D_CD ) LEFT OUTER JOIN ( SELECT D.SYST_VAL_D_CD, D.SYST_VAL_D_NM FROM TB_SYST_VAL_D D WHERE D.SYST_VAL_CD = 'SYS053' AND D.USE_YN = 'Y' ) CS ON ( AT.COMPLETION_STATUS_CD = CS.SYST_VAL_D_CD ) WHERE AT.CMPNY_CD = #{gvCmpnyCd} AND AT.SESSION_CD = #{sessionCd} AND AT.DEL_YN = 'N'
AND AT.USER_TYPE_CD = #{userTypeCd}
AND AT.COMPLETION_STATUS_CD = #{completionStatusCd}
ORDER BY AT.ENTRY_AT IS NULL, AT.ENTRY_AT, AT.ATTENDANCE_CD

/* Tbm04Mapper.selectAttendanceEventCount */
SELECT COUNT(1)
FROM TB_TBM_ATTENDANCE_EVENT EV
WHERE EV.CMPNY_CD = #{gvCmpnyCd}
  AND EV.ATTENDANCE_CD = #{attendanceCd}

mapper.update:
/* Tbm04Mapper.updateCompletion */
UPDATE TB_TBM_ATTENDANCE
SET
	COMPLETION_STATUS_CD	= #{completionStatusCd}
	/* NOT_COMPLETED 시에만 사유 갱신. COMPLETED 복귀 시 기존 사유 보존(감사용). */
	, NOT_COMPLETED_REASON	= IFNULL(#{notCompletedReason}, NOT_COMPLETED_REASON)
	, STATUS_UPDATED_BY		= #{gvUserCd}
	, STATUS_UPDATED_AT		= NOW()
	, UPDATE_NO				= #{gvUserCd}
	, UPDATE_DATE			= NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND ATTENDANCE_CD = #{attendanceCd}
  AND DEL_YN = 'N'

mapper.select:
/* Tbm04Mapper.selectUserInfo */
SELECT DU.USER_CD AS userCd , 'DAILY' AS userTypeCd , DU.USER_NM AS userNm , DU.SITE_CD AS siteCd , ST.SITE_NM AS siteNm , NULL AS deptNm , DU.MBL_NO_LAST4 AS mblNoLast4 FROM TB_DAILY_USER DU LEFT OUTER JOIN TB_SITE ST ON ( DU.CMPNY_CD = ST.CMPNY_CD AND DU.SITE_CD = ST.SITE_CD ) WHERE DU.CMPNY_CD = #{gvCmpnyCd} AND DU.USER_CD = #{userCd}
SELECT RU.USER_CD AS userCd , 'REGULAR' AS userTypeCd , RU.USER_NM AS userNm , RU.SITE_CD AS siteCd , ST.SITE_NM AS siteNm , ND.NODE_NM AS deptNm , NULL AS mblNoLast4 FROM TB_USER RU LEFT OUTER JOIN TB_SITE ST ON ( RU.CMPNY_CD = ST.CMPNY_CD AND RU.SITE_CD = ST.SITE_CD ) LEFT OUTER JOIN TB_SITE_NODE ND ON ( RU.CMPNY_CD = ND.CMPNY_CD AND RU.SITE_CD = ND.SITE_CD AND RU.NODE_CD = ND.NODE_CD ) WHERE RU.CMPNY_CD = #{gvCmpnyCd} AND RU.USER_CD = #{userCd}

mapper.sql:
WHERE AT.CMPNY_CD = #{gvCmpnyCd}
  AND AT.USER_TYPE_CD = #{userTypeCd}
  AND AT.USER_CD = #{userCd}
  AND AT.DEL_YN = 'N'

    AND AT.COMPLETION_STATUS_CD = #{completionStatusCd}


    AND DATE(IFNULL(S.ENDED_AT, S.INSERT_DATE)) >= #{startDate}


    AND DATE(IFNULL(S.ENDED_AT, S.INSERT_DATE)) <= #{endDate}
